from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core.entities.collector import CommonOamCollector, Collector
from taf.collectors.core.entities.async_collector import AsyncCollector

import time
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CoamSnapshotCollector(CommonOamCollector):
    """
    Generation of a Coam snapshot is triggered at the REST API and the result is stored locally in the directory
    target_dir, that is given to the collect() call.
    """

    def __init__(self,
                 coverage=None,
                 force=None,
                 timeout=None,
                 reg_exp_filter=None,
                 reason=None,
                 network_cell_dns=None,
                 target_file_name=None,
                 **kwargs):
        super(CoamSnapshotCollector, self).__init__(**kwargs)
        self._get_snapshot_args = {
            "coverage": coverage,
            "force": force,
            "timeout": timeout,
            "reg_exp_filter": reg_exp_filter,
            "reason": reason,
            "network_cell_dns": network_cell_dns
        }
        self._get_snapshot_args = {k: v for k, v in self._get_snapshot_args.items() if v is not None}
        self._target_file_name = target_file_name or "snapshot.zip"

    def _collect(self, target_dir):
        """
        Transfer the information, that shall be collected, from the remote host to the local host.

        :param str target_dir: target path, where collected information shall be stored on the local host
        """
        snapshot_path = "{target_dir}/{target_file_name}".format(
            target_dir=target_dir,
            target_file_name=self._target_file_name)
        logger.debug(
            "creating Coam snapshot with "
            " snapshot path {snapshot_path!r} "
            " & other arguments {collecting_details!r} ".format(
                snapshot_path=snapshot_path,
                collecting_details=self._get_snapshot_args
            ))
        self._managed_admin_connection.get_snapshot(target_file_name=snapshot_path,
                                                    **self._get_snapshot_args)


