class SbtsScrelCollector(CommonOamCollector):
    """
    Generation of a Coam SCREL is triggered at the REST API and the result is stored local in the
    directory target_dir, that is given to the collect() call.
    """

    def __init__(self,
                 include_pmfm_data=None,
                 target_file_name=None,
                 timeout=None,
                 **kwargs):
        super(SbtsScrelCollector, self).__init__(**kwargs)

        self._get_screl_args = {}

        if include_pmfm_data is not None:
            self._get_screl_args["include_pmfm_data"] = include_pmfm_data

        if timeout is not None:
            self._get_screl_args["timeout"] = float(timeout)

        if target_file_name is None:
            target_file_name = "SCREL.zip"
        self._target_file_name = target_file_name

    def _collect(self, target_dir):
        """
        Transfer the information, that shall be collected to the local host.

        :param str target_dir: target path, where collected information shall be stored on the host.
        """
        screl_path = "{target_dir}/{target_file_name}".format(
            target_dir=target_dir,
            target_file_name=self._target_file_name)
        logger.debug(
            "creating Coam screl with "
            " screl path {screl_path!r} "
            " & other arguments {collecting_details!r} ".format(
                screl_path=screl_path,
                collecting_details=self._get_screl_args
            ))
        self._managed_admin_connection.collect_local_screl(target_file_name=screl_path, **self._get_screl_args)


