class AsynchronousCoamScrelCollectorBase(AsyncCollector):
    def __init__(self,
                 **kwargs):
        super(AsynchronousCoamScrelCollectorBase, self).__init__(**kwargs)
        self._managed_admin_connection = None

    def _get_screl_status(self, operation_id, timeout=300):
        end_time = time.time() + timeout
        while time.time() < end_time:
            time.sleep(5)
            self.operation_info = self._managed_admin_connection.get_screl_operation_info(operation_id=operation_id,
                                                                                          timeout=timeout)
            status = self.operation_info['status']
            logger.debug("SCREL status is {status} for operation_id: "
                         "{operation_id}".format(status=status,
                                                 operation_id=self.operation_info['operationId']))
            if status == "succeeded":
                break
            elif status == "ongoing":
                yield status
            else:
                raise RuntimeError("unexpected SCREL operation status: {status}".format(status=status))

    def awaitable(self, operation_id, target_dir, timeout=300):
        for status in self._get_screl_status(operation_id=operation_id, timeout=timeout):
            yield status
        self._managed_admin_connection.download_screl_files(directory=target_dir,
                                                            operation_id=self.operation_info['operationId'],
                                                            files_list=self.operation_info['files'],
                                                            compressed=self._get_screl_args.pop('compressed', False),
                                                            **self._get_screl_args)


class AsynchronousCoamVDUScrelCollector(Using("managed_vdu_connection"), AsynchronousCoamScrelCollectorBase,
                                        CoamScrelCollectorBase):
    """
    Generation of a Coam VDU asynchronous SCREL is triggered at the REST API and the result is stored locally in
    the directory target_dir, that is given to the async_collect() call.
    """

    def __init__(self,
                 **kwargs):
        super(AsynchronousCoamVDUScrelCollector, self).__init__(**kwargs)
        self._managed_admin_connection = self._managed_vdu_connection

    def _async_collect(self, target_dir):
        """
        Transfer the information, that shall be collected, from the remote host to the local host.

        :param str target_dir: target path, where collected information shall be stored on the local host
        """
        logger.debug(
            "creating Coam VDU SCREL with "
            "SCREL path {screl_path!r} "
            "& other arguments {collecting_details!r} ".format(
                screl_path=target_dir,
                collecting_details=self._get_screl_args
            ))
        operation_info = self._managed_admin_connection.trigger_screl_collection(
            **{'coverage': self._get_screl_args.pop('coverage')} if 'coverage' in self._get_screl_args else {})
        awaitables = [self.awaitable(operation_info['operationId'], target_dir)]
        return awaitables


